cat > /tmp/verify_sticky.py << 'EOF'
from playwright.sync_api import sync_playwright

PAGES = ['index.php', 'energy.php', 'ecosystem.php', 'partners.php', 'contact.php']
VIEWPORTS = [(1920, 1080), (1440, 900), (375, 812)]

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)

    all_errors = []
    fail = False

    for vw, vh in VIEWPORTS:
        for pg in PAGES:
            context = browser.new_context(ignore_https_errors=True, viewport={"width": vw, "height": vh})
            page = context.new_page()
            errs = []
            page.on("console", lambda msg: errs.append(msg.text) if msg.type == "error" else None)

            url = f'https://127.0.0.1:5110/nexifynewweb/{pg}'
            page.goto(url)
            page.wait_for_load_state("domcontentloaded")
            page.wait_for_timeout(400)

            # Scroll down 1500px
            page.evaluate("window.scrollTo(0, 1500)")
            page.wait_for_timeout(300)

            in_viewport = page.evaluate("""
                () => {
                    const h = document.querySelector('.site-header');
                    if (!h) return null;
                    const rect = h.getBoundingClientRect();
                    return { top: rect.top, height: rect.height, hasScrolled: h.classList.contains('is-scrolled') };
                }
            """)

            sticky_ok = in_viewport and abs(in_viewport['top']) < 5
            status = "OK" if sticky_ok else "FAIL"
            print(f"[{status}] {vw}x{vh} {pg}: top={in_viewport['top']}, is-scrolled={in_viewport['hasScrolled']}")

            if not sticky_ok:
                fail = True

            if errs:
                all_errors.extend([f"{pg}: {e}" for e in errs])

            # Save screenshot for first page
            if pg == 'index.php':
                page.screenshot(path=f'/tmp/sticky_{vw}x{vh}.png', full_page=False)

            context.close()

    if all_errors:
        print(f"\nConsole errors:")
        for e in all_errors:
            print(f"  - {e}")
    else:
        print("\nNo console errors")

    browser.close()

    if fail:
        print("\n❌ STICKY HEADER FAILED ON SOME PAGES")
    else:
        print("\n✅ STICKY HEADER WORKING ON ALL PAGES/VIEWPORTS")
EOF
